/**
 * GENERATED by `node scripts/generate-package-manifest.mjs` — do not edit.
 *
 * Every `package.json` in the repo and the dependency ranges it declares, as
 * plain data. The Tech portal's Package Updates console reads this through
 * `packageUpdatesService`, which asks the npm registry what each of these is
 * published at today.
 *
 * It is a generated FILE rather than a directory walk because the API's Docker
 * image only ever copies the manifests `pnpm install` needs — two thirds of
 * the repo is not in it, and a walk would report on the rest as if it were
 * everything.
 */

/** The block of a `package.json` a dependency was declared in. */
export type ManifestDependencyKind =
  | 'dependencies'
  | 'devDependencies'
  | 'peerDependencies'
  | 'optionalDependencies';

export interface ManifestDependency {
  name: string;
  /** Exactly what the manifest declares — `^1.2.3`, `workspace:*`, `git+…`. */
  range: string;
  kind: ManifestDependencyKind;
}

export interface ManifestPackage {
  /** The manifest's `name`, or its repo path when it declares none. */
  name: string;
  /** Repo-relative, forward-slashed path to the `package.json`. */
  path: string;
  private: boolean;
  dependencies: ManifestDependency[];
}

